import { test, expect } from '@playwright/test';

test.describe('Profile Picture Upload and Preview', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user/profile');
  });

  test('should successfully upload a profile picture and display preview', async ({ page }) => {
    // Verify profile picture upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload profile picture/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button to open file dialog
    await uploadButton.click();

    // Intercept file upload API
    await page.route('**/api/user/profile/picture', (route) => {
      route.abort('blockedbyclient');
    });

    // Set up file upload listener
    const uploadPromise = page.waitForResponse(response =>
      response.url().includes('/api/user/profile/picture') && response.status() === 200
    );

    // Upload a valid image file
    const fileInput = page.locator('[data-testid="profile-picture-upload-input"]');
    await fileInput.setInputFiles('playwright/fixtures/profile-pic.jpg');

    // Wait for upload response
    const response = await uploadPromise;
    expect(response.status()).toBe(200);

    // Verify preview image is displayed
    const previewImage = page.getByRole('img', { name: /profile picture preview/i });
    await expect(previewImage).toBeVisible();
    await expect(previewImage).toHaveAttribute('src', /profile-pic\.jpg/);

    // Verify preview has correct dimensions
    const previewContainer = page.locator('[data-testid="profile-picture-preview-container"]');
    await expect(previewContainer).toHaveCSS('width', '100px');
    await expect(previewContainer).toHaveCSS('height', '100px');

    // Verify upload success message
    const successMessage = page.getByText(/profile picture uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify upload button is disabled
    await expect(uploadButton).toBeDisabled();
  });

  test('should handle file upload errors and display appropriate messages', async ({ page }) => {
    // Verify profile picture upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload profile picture/i });
    await expect(uploadButton).toBeVisible();

    // Intercept file upload API and simulate error
    await page.route('**/api/user/profile/picture', (route) => {
      route.abort('blockedbyclient');
    });

    // Set up error response listener
    const errorPromise = page.waitForResponse(response =>
      response.url().includes('/api/user/profile/picture') && response.status() === 500
    );

    // Upload a file that triggers server error
    const fileInput = page.locator('[data-testid="profile-picture-upload-input"]');
    await fileInput.setInputFiles('playwright/fixtures/large_file.png');

    // Wait for error response
    const response = await errorPromise;
    expect(response.status()).toBe(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to upload profile picture/i);
    await expect(errorMessage).toBeVisible();

    // Verify preview image does not appear
    const previewImage = page.getByRole('img', { name: /profile picture preview/i });
    await expect(previewImage).not.toBeVisible();

    // Verify upload button is re-enabled
    await expect(uploadButton).toBeEnabled();

    // Verify error state is visible
    const errorState = page.locator('[data-testid="upload-error-state"]');
    await expect(errorState).toBeVisible();
  });
});
